"""Derive the world-only speed SDK without changing the pinned Sunset runtime."""
import argparse
import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SOURCE_SHA256 = '8773f09fa7d66df0317d80e51d034358c0330f62dfece640c45a8dbf418a38e6'


def generate():
    original = (ROOT / 'web/public/emulator/mgba.sdk.js').read_bytes()
    if hashlib.sha256(original).hexdigest() != SOURCE_SHA256:
        raise ValueError('Pinned Sunset SDK changed; review before deriving the world runtime')
    source = original.decode()
    changes = [
        ('    let coreRate = 0;', '    let playbackSpeed = 1;\n    let coreRate = 0;'),
        ('const rate = mod._mgbawasm_sample_rate();',
         'const rate = mod._mgbawasm_sample_rate() * playbackSpeed;'),
        ('* framerate);', '* framerate * playbackSpeed);'),
        ('Math.min(MAX_FRAMES_PER_TICK, frames)',
         'Math.min(MAX_FRAMES_PER_TICK * playbackSpeed, frames)'),
        ('        config: engineConfig,', '''        // Speed is host presentation state: never written into the guest or Flash.
        getSpeed() { return playbackSpeed; },
        setSpeed(value) {
            if (value !== 1 && value !== 2)
                throw new RangeError('World playback speed must be 1 or 2.');
            if (value === playbackSpeed) return playbackSpeed;
            // A measurement cannot silently span two different playback rates.
            performanceProbe?.stop('speed-change');
            playbackSpeed = value;
            // Re-anchor instead of applying the new multiplier to elapsed old time.
            wallClockStart = performance.now();
            wallClockFrames = 0;
            syncCoreRate();
            emit({ type: 'speed', speed: playbackSpeed });
            return playbackSpeed;
        },
        config: engineConfig,'''),
    ]
    for before, after in changes:
        if source.count(before) != 1:
            raise ValueError('World speed patch anchor changed: ' + before)
        source = source.replace(before, after, 1)
    source = source.replace('//# sourceMappingURL=mgba.sdk.js.map\n', '')
    return ('// Generated by scripts/quality/generate_world_runtime.py; world only.\n'
            '// Pinned upstream SDK SHA256: ' + SOURCE_SHA256 + '\n' + source)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    target = ROOT / 'web/public/emulator/world.sdk.js'
    expected = generate()
    if args.check:
        if target.read_text() != expected:
            raise SystemExit('World SDK differs from the reviewed generator')
        print('World SDK matches its pinned source and speed-only derivation.')
    else:
        target.write_text(expected)
